    vector<pair<int,int>> act(n);
    for(int i=0;i<n;i++) act[i]={finish[i],start[i]};
    sort(act.begin(),act.end());
    int count=1, lastFinish=act[0].first;
    for(int i=1;i<n;i++) {
        if(act[i].second>=lastFinish) {
            count++;
            lastFinish=act[i].first;
        }
    }
    return count;
}

