def fractional_knapsack(W, values, weights, n):
    items = sorted(range(n), key=lambda i: values[i]/weights[i], reverse=True)
    total = 0.0
    for i in items:
        if W >= weights[i]:
            total += values[i]
            W -= weights[i]
        else:
            total += values[i] * (W / weights[i])
            break
    return total

