struct Cmp { bool operator()(Node* a, Node* b){ return a->freq > b->freq; } };
void getCodes(Node* root, string code, map<char,string>& codes) {
    if(!root) return;
    if(!root->left && !root->right) { codes[root->ch]=code.empty()?"0":code; return; }
    getCodes(root->left, code+"0", codes);
    getCodes(root->right, code+"1", codes);
}
void buildHuffmanCodes(char chars[], int freq[], int n) {
    priority_queue<Node*,vector<Node*>,Cmp> pq;
    for(int i=0;i<n;i++) pq.push(new Node(chars[i],freq[i]));
    while(pq.size()>1) {
        Node *l=pq.top(); pq.pop(); Node *r=pq.top(); pq.pop();
        Node *p=new Node('\0',l->freq+r->freq); p->left=l; p->right=r;
        pq.push(p);
    }
    map<char,string> codes;
    getCodes(pq.top(),"",codes);
    for(auto& [c,code]:codes) cout<<c<<": "<<code<<endl;
}

