def build_huffman_codes(chars, freq, n):
    class Node:
        def __init__(self, ch, f): self.ch, self.freq, self.left, self.right = ch, f, None, None
        def __lt__(self, o): return self.freq < o.freq
    heap = [Node(chars[i], freq[i]) for i in range(n)]
    heapq.heapify(heap)
    while len(heap) > 1:
        l, r = heapq.heappop(heap), heapq.heappop(heap)
        p = Node(None, l.freq+r.freq); p.left, p.right = l, r
        heapq.heappush(heap, p)
    codes = {}
    def dfs(node, code):
        if not node: return
        if not node.left and not node.right: codes[node.ch] = code or '0'; return
        dfs(node.left, code+'0'); dfs(node.right, code+'1')
    dfs(heap[0], '')
    for c in sorted(codes): print(f'{c}: {codes[c]}')

