int primMST(int V, vector<vector<pair<int,int>>>& adj) {
    vector<bool> inMST(V,false);
    priority_queue<pair<int,int>,vector<pair<int,int>>,greater<>> pq;
    pq.push({0,0});
    int mst=0;
    while(!pq.empty()) {
        auto [w,u]=pq.top(); pq.pop();
        if(inMST[u]) continue;
        inMST[u]=true; mst+=w;
        for(auto& [v,wt]:adj[u])
            if(!inMST[v]) pq.push({wt,v});
    }
    return mst;
}

