pair<int,int> jobSequencing(vector<tuple<int,int,int>>& jobs, int n) {
    sort(jobs.begin(),jobs.end(),[](auto& a, auto& b){return get<2>(a)>get<2>(b);});
    int maxD=0;
    for(auto&[id,d,p]:jobs) maxD=max(maxD,d);
    vector<bool> slot(maxD+1,false);
    int count=0,profit=0;
    for(auto&[id,d,p]:jobs) {
        for(int j=d;j>=1;j--) {
            if(!slot[j]) { slot[j]=true; count++; profit+=p; break; }
        }
    }
    return {count,profit};
}

