def job_sequencing(jobs, n):
    jobs.sort(key=lambda x: -x[2])
    max_d = max(d for _,d,_ in jobs)
    slot = [False]*(max_d+1)
    count, profit = 0, 0
    for _,d,p in jobs:
        for j in range(d, 0, -1):
            if not slot[j]:
                slot[j] = True
                count += 1
                profit += p
                break
    return count, profit

