long long optimalMerge(vector<int>& sizes, int n) {
    priority_queue<long long, vector<long long>, greater<>> pq(sizes.begin(), sizes.end());
    long long totalCost = 0;
    while(pq.size() > 1) {
        long long a = pq.top(); pq.pop();
        long long b = pq.top(); pq.pop();
        long long merged = a + b;
        totalCost += merged;
        pq.push(merged);
    }
    return totalCost;
}

