def dijkstra(V, adj, S):
    dist = [float('inf')]*V
    dist[S] = 0
    heap = [(0, S)]
    while heap:
        d, u = heapq.heappop(heap)
        if d > dist[u]: continue
        for v, w in adj[u]:
            if dist[u]+w < dist[v]:
                dist[v] = dist[u]+w
                heapq.heappush(heap, (dist[v], v))
    return [d if d != float('inf') else -1 for d in dist]
